import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Independently undo the bounded ports and compare every original method and archive entry. */
public final class CompanionForestAreaDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",A=P+"NativeAreaMaterialAction",F=P+"ForcedCombat",H=P+"NativeCompanionForestArea";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static byte[] method(ClassNode c,MethodNode m,String name){var q=new ClassNode();q.version=c.version;q.access=c.access;q.name=c.name;q.superName=c.superName;var copy=new MethodNode(m.access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(copy);q.methods.add(copy);var w=new ClassWriter(0);q.accept(w);return w.toByteArray();}
 static MethodNode find(ClassNode c,String name,String desc){return c.methods.stream().filter(m->m.name.equals(name)&&m.desc.equals(desc)).findFirst().orElseThrow();}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static void loads(MethodNode m,AbstractInsnNode n,int[] ops,int[] locals){for(int i=ops.length-1;i>=0;i--){var q=prev(n);if(!(q instanceof VarInsnNode v)||v.getOpcode()!=ops[i]||v.var!=locals[i])throw new AssertionError("port argument");m.instructions.remove(q);}}
 public static void main(String[]args)throws Exception{try(var before=new JarFile(args[0]);var after=new JarFile(args[1])){
  var old=new HashSet<String>();var changed=new TreeSet<String>();for(var e:Collections.list(before.entries())){old.add(e.getName());var q=after.getJarEntry(e.getName());if(q==null)throw new AssertionError("removed entry");if(!Arrays.equals(before.getInputStream(e).readAllBytes(),after.getInputStream(q).readAllBytes()))changed.add(e.getName());}var fresh=new TreeSet<String>();for(var e:Collections.list(after.entries()))if(!old.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(Set.of(PC+".class",A+".class",F+".class"))||!fresh.equals(Set.of(H+".class",P+"NativeSelectorOnlyCtrl.class")))throw new AssertionError("archive boundary "+changed+fresh);
  int empty=0,apply=0,run=0;for(String name:List.of(PC,A,F)){var b=read(before,name);var a=read(after,name);if(b.fields.size()!=a.fields.size())throw new AssertionError("new fields");for(int i=0;i<b.fields.size();i++){var x=b.fields.get(i);var y=a.fields.get(i);if(!x.name.equals(y.name)||!x.desc.equals(y.desc)||x.access!=y.access||!Objects.equals(x.value,y.value))throw new AssertionError("field schema");}
   if(a.methods.size()!=b.methods.size()+(name.equals(A)?0:1))throw new AssertionError("method schema");
   for(var original:b.methods){var m=find(a,name.equals(F)&&original.name.equals("unwrap")?"nativeForestOriginalUnwrap":original.name,original.desc);
    if(name.equals(PC)&&m.name.equals("nativeMaterialAreaSilenceBody"))for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(H)){
     if(v.name.equals("empty")){loads(m,v,new int[]{Opcodes.ALOAD,Opcodes.ALOAD},new int[]{0,2});m.instructions.set(v,new MethodInsnNode(Opcodes.INVOKEINTERFACE,"java/util/List","isEmpty","()Z",true));empty++;}
     else if(v.name.equals("apply")){loads(m,v,new int[]{Opcodes.ALOAD,Opcodes.ALOAD,Opcodes.ILOAD,Opcodes.ILOAD,Opcodes.ILOAD,Opcodes.ILOAD,Opcodes.LLOAD},new int[]{0,2,22,23,26,3,29});m.instructions.remove(v);apply++;}else throw new AssertionError("unexpected hook");
    }
    if(name.equals(A)&&m.name.equals("run"))for(var n:m.instructions)if(n instanceof MethodInsnNode v&&v.owner.equals(H)&&v.name.equals("run")){v.owner=P+"NativeCompanionArea";run++;}
    if(!Arrays.equals(method(b,original,original.name),method(a,m,original.name)))throw new AssertionError("original method changed "+name+"."+original.name);
   }
   if(name.equals(PC)){var original=b.methods.stream().filter(m->m.name.equals("combatProbability$10")).findFirst().orElseThrow();var alias=find(a,"nativeForestSilenceChance",original.desc);int access=alias.access;alias.access=original.access;if(!Arrays.equals(method(b,original,original.name),method(a,alias,original.name)))throw new AssertionError("probability clone");alias.access=access;}
  }if(empty!=1||apply!=1||run!=1)throw new AssertionError("port counts");
  for(String name:List.of(H,P+"NativeSelectorOnlyCtrl")){var c=read(after,name);if(!c.fields.isEmpty())throw new AssertionError("stateful helper");for(var m:c.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==Opcodes.NEW&&(t.desc.equals("java/lang/ThreadLocal")||t.desc.equals("java/lang/Thread")||t.desc.contains("Executor")))throw new AssertionError("new lifetime owner "+t.desc);if(n instanceof MethodInsnNode v&&(v.owner.startsWith("java/sql/")||v.owner.startsWith("java/nio/file/")||v.owner.contains("AccountRepository")||v.owner.contains("GameStateStore")||v.owner.equals("java/lang/Thread")||v.owner.contains("Executor")))throw new AssertionError("new IO/lifetime owner "+v.owner);}}
 }System.out.println("PASS three changed/two stateless fresh classes; exact inverse ports; all original methods, Ctrl permissions, Context, fields and remaining archive retained; original probability clone; no new SQL/file/worker dependencies or owned TLS");}
}
